1	// Pure reducer: folds audit events into screen state. Every panel renders only this state.
2	// The UI computes nothing itself except the running totals of llm_call events (section 16).
3	import type { Agent, AuditEvent, BacktestResultEvent, BaselineStats, EquityPoint, Stats, VerdictEvent } from "./events";
4	
5	export type AgentStatus = "idle" | "active" | "done" | "error";
6	export const agentOrder: Agent[] = ["planner", "researcher", "mathematician", "naysayer", "reporter"];
7	
8	/** One follow-up card: the Naysayer's request, then the Mathematician's result merged in by id. */
9	export interface Followup {
10	  id: string;
11	  reason: string;
12	  title?: string;
13	  result?: string;
14	  downgrade?: boolean;
15	  cause?: string | null;
16	  skipped?: boolean;
17	}
18	
19	export interface UiState {
20	  phase: "idle" | "running" | "done";
21	  idea: string;
22	  provider: string | null;
23	  startedAt: string | null;
24	  traceId: string | null;
25	  whatTested: string | null;
26	  planHash: string | null;
27	  agents: Record<Agent, AgentStatus>;
28	  lastAgent: Agent | null;
29	  links: { from: Agent; to: Agent; key: number } | null;
30	  equityTrain: EquityPoint[];
31	  equityValidation: EquityPoint[];
32	  equityRun: string | null;
33	  stats: { train: Stats; validation: Stats; baseline: BaselineStats } | null;
34	  followups: Followup[];
35	  followupsRun: number;
36	  checks: { check: string; passed: boolean; value: unknown; note: string }[];
37	  recoveries: { failed: string; action: string; injected: boolean }[];
38	  verdict: VerdictEvent["payload"] | null;
39	  report: { path: string; traceId: string | null } | null;
40	  meters: { llmCalls: number; budget: number; promptTokens: number; completionTokens: number; costUsd: number };
41	  lastSeq: number;
42	  lastTs: string | null;
43	  errors: string[];
44	}
45	
46	export const initialState: UiState = {
47	  phase: "idle",
48	  idea: "",
49	  provider: null,
50	  startedAt: null,
51	  traceId: null,
52	  whatTested: null,
53	  planHash: null,
54	  agents: { planner: "idle", researcher: "idle", mathematician: "idle", naysayer: "idle", reporter: "idle", triage: "idle" },
55	  lastAgent: null,
56	  links: null,
57	  equityTrain: [],
58	  equityValidation: [],
59	  equityRun: null,
60	  stats: null,
61	  followups: [],
62	  followupsRun: 0,
63	  checks: [],
64	  recoveries: [],
65	  verdict: null,
66	  report: null,
67	  meters: { llmCalls: 0, budget: 8, promptTokens: 0, completionTokens: 0, costUsd: 0 },
68	  lastSeq: 0,
69	  lastTs: null,
70	  errors: [],
71	};
72	
73	let linkKey = 0;
74	const link = (from: Agent, to: Agent) => ({ from, to, key: ++linkKey });
75	
76	/** Copy only the M2 result fields that are present and well typed; M1 event files have none of them. */
77	function followupResult(p: BacktestResultEvent["payload"]): Partial<Followup> {
78	  const out: Partial<Followup> = {};
79	  if (typeof p.title === "string") out.title = p.title;
80	  if (typeof p.result === "string") out.result = p.result;
81	  if (typeof p.downgrade === "boolean") out.downgrade = p.downgrade;
82	  if (typeof p.cause === "string" || p.cause === null) out.cause = p.cause;
83	  if (p.skipped === true) out.skipped = true;
84	  return out;
85	}
86	
87	/** The verdict's applied downgrade for this follow-up, matched by cause; null if none was applied. */
88	export function appliedDowngrade(f: Followup, verdict: UiState["verdict"]): VerdictEvent["payload"]["downgrades"][number] | null {
89	  if (!f.downgrade || !f.cause || !verdict) return null;
90	  return verdict.downgrades.find((d) => d.cause === f.cause) ?? null;
91	}
92	
93	function summaryField(summary: unknown, field: string): string | null {
94	  if (summary && typeof summary === "object" && field in summary) {
95	    const v = (summary as Record<string, unknown>)[field];
96	    return typeof v === "string" ? v : null;
97	  }
98	  return null;
99	}
100	
101	export function reduce(prev: UiState, e: AuditEvent): UiState {
102	  const s: UiState = { ...prev, lastSeq: e.seq, lastTs: e.ts };
103	  switch (e.type) {
104	    case "audit_started":
105	      return { ...s, phase: "running", idea: e.payload.idea, provider: e.payload.provider ?? null, startedAt: e.ts, traceId: e.payload.trace_id,
106	        meters: { ...s.meters, budget: e.payload.llm_budget } };
107	    case "agent_started":
108	      return { ...s, phase: s.phase === "idle" ? "running" : s.phase,
109	        agents: { ...s.agents, [e.agent]: "active" },
110	        links: s.lastAgent && s.lastAgent !== e.agent ? link(s.lastAgent, e.agent) : s.links,
111	        lastAgent: e.agent };
112	    case "agent_finished":
113	      return { ...s, agents: { ...s.agents, [e.agent]: e.payload.status === "error" ? "error" : "done" },
114	        whatTested: summaryField(e.payload.summary, "what_tested") ?? s.whatTested,
115	        planHash: summaryField(e.payload.summary, "plan_hash") ?? s.planHash };
116	    case "llm_call": {
117	      const m = s.meters;
118	      return { ...s, meters: { ...m, llmCalls: m.llmCalls + 1, promptTokens: m.promptTokens + e.payload.prompt_tokens,
119	        completionTokens: m.completionTokens + e.payload.completion_tokens, costUsd: m.costUsd + e.payload.cost_usd } };
120	    }
121	    case "backtest_result": {
122	      const run = e.payload.run;
123	      if (/^F\d/.test(run)) {
124	        const got = followupResult(e.payload);
125	        const known = s.followups.some((f) => f.id === run);
126	        return { ...s, followupsRun: s.followupsRun + 1,
127	          followups: known ? s.followups.map((f) => (f.id === run ? { ...f, ...got } : f)) : [...s.followups, { id: run, reason: "", ...got }] };
128	      }
129	      if (run !== "base") return s;
130	      return { ...s, equityTrain: e.payload.equity_train, equityValidation: e.payload.equity_validation,
131	        equityRun: e.payload.run, stats: { train: e.payload.train, validation: e.payload.validation, baseline: e.payload.baseline } };
132	    }
133	    case "check_result":
134	      return { ...s, checks: [...s.checks, e.payload] };
135	    case "followup_requested":
136	      return { ...s, followups: [...s.followups, { id: e.payload.followup, reason: e.payload.reason }],
137	        links: link("naysayer", "mathematician") };
138	    case "recovered":
139	      return { ...s, recoveries: [...s.recoveries, e.payload] };
140	    case "verdict": {
141	      // Tolerate a payload with missing parts so one odd line never blanks the screen.
142	      const p = e.payload ?? ({} as VerdictEvent["payload"]);
143	      const headline = p.headline && typeof p.headline === "object" ? p.headline : {};
144	      const downgrades = Array.isArray(p.downgrades) ? p.downgrades : [];
145	      return { ...s, phase: "done", verdict: { ...p, verdict: p.verdict, reason: typeof p.reason === "string" ? p.reason : "", headline, downgrades } };
146	    }
147	    case "report_ready":
148	      return { ...s, report: { path: e.payload.path, traceId: e.payload.trace_id }, agents: { ...s.agents, reporter: "done" } };
149	    case "error":
150	      return { ...s, phase: "done", errors: [...s.errors, `${e.payload.step}: ${e.payload.message}`],
151	        agents: e.agent ? { ...s.agents, [e.agent]: "error" } : s.agents };
152	    default:
153	      return s;
154	  }
155	}
