// Agent graph: the section 4 loop as a vertical list of five agents on a rail. HTML text, not a scaled SVG,
// so labels keep their real size (12-14 px) at 1280 and in a 1080p recording. Every animation marks an event:
// a row lights on agent_started and settles on agent_finished, a dot travels the rail when work moves
// (links.key changes), and the return arc lights once the Naysayer has requested follow-ups.
import { motion } from "framer-motion";
import type { Agent } from "../events";
import { agentOrder, type AgentStatus, type UiState } from "../state";

export const AGENT_LABEL: Record<Agent, string> = {
  planner: "Planner", researcher: "Researcher", mathematician: "Mathematician", naysayer: "Naysayer", reporter: "Reporter", triage: "Triage",
};
const STATUS_TEXT: Record<AgentStatus, string> = { idle: "standby", active: "active", done: "done", error: "error" };
const STATUS_COLOR: Record<AgentStatus, string> = { idle: "text-muted", active: "text-accent", done: "text-promising", error: "text-kill" };
const ROW_BORDER: Record<AgentStatus, string> = { idle: "border-line", active: "border-accent", done: "border-promising/50", error: "border-kill" };
const MARKER: Record<AgentStatus, string> = { idle: "border-line bg-bg", active: "border-accent bg-accent", done: "border-promising bg-promising", error: "border-kill bg-kill" };

const ROW = 44, GAP = 6, STEP = ROW + GAP, RAIL_X = 11;
const centre = (a: Agent) => agentOrder.indexOf(a) * STEP + ROW / 2;

export function AgentGraph({ state, reduced }: { state: UiState; reduced: boolean }) {
  const followups = state.followups.length;
  const height = agentOrder.length * STEP - GAP;
  const yM = centre("mathematician"), yN = centre("naysayer");
  return (
    <div className="relative shrink-0" style={{ height }}>
      {/* rail and one marker per agent */}
      <div aria-hidden className="absolute w-0.5 bg-line" style={{ left: RAIL_X - 1, top: ROW / 2, height: height - ROW }} />
      {agentOrder.map((a) => (
        <span key={a} aria-hidden className={`absolute size-3 rounded-full border-2 transition-colors duration-200 ${MARKER[state.agents[a]]}`} style={{ left: RAIL_X - 6, top: centre(a) - 6 }} />
      ))}

      {/* travelling dot, remounted on every handoff */}
      {!reduced && state.links && (
        <motion.span
          key={state.links.key}
          aria-hidden
          className="absolute size-3 rounded-full bg-accent shadow-[0_0_10px_var(--color-accent)]"
          style={{ left: RAIL_X - 6, top: 0 }}
          initial={{ y: centre(state.links.from) - 6, opacity: 1 }}
          animate={{ y: centre(state.links.to) - 6, opacity: [1, 1, 0] }}
          transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
        />
      )}

      {/* return arc: the Naysayer sends follow-ups back to the Mathematician */}
      <svg aria-hidden className="absolute top-0 right-0 overflow-visible" width={40} height={height}>
        <path
          d={`M 0 ${yN} C 34 ${yN}, 34 ${yM}, 0 ${yM}`}
          fill="none"
          strokeWidth={2}
          strokeDasharray="5 5"
          style={{ stroke: followups ? "var(--color-accent)" : "var(--color-line)", transition: "stroke 200ms" }}
        />
        {followups > 0 && (
          <text x={30} y={(yM + yN) / 2 + 4} className="font-mono" fontSize={12} fill="var(--color-accent)">×{followups}</text>
        )}
      </svg>

      <ol aria-label="Agents" className="flex flex-col pr-11 pl-7" style={{ gap: GAP }}>
        {agentOrder.map((agent) => {
          const status = state.agents[agent];
          const glow = status === "active" && !reduced ? "shadow-[0_0_14px_-4px_var(--color-accent)]" : "";
          return (
            <li
              key={agent}
              className={`flex min-w-0 items-center justify-between gap-3 rounded-md border bg-bg px-3 transition-[border-color,box-shadow] duration-200 ${ROW_BORDER[status]} ${glow}`}
              style={{ height: ROW }}
            >
              <span className={`truncate text-sm font-semibold ${status === "idle" ? "text-muted" : "text-text"}`}>{AGENT_LABEL[agent]}</span>
              <span className="flex shrink-0 items-center gap-2">
                {agent === "researcher" && state.recoveries.map((r, i) => (
                  <span
                    key={i}
                    title={`Recovered: ${r.failed} → ${r.action}`}
                    className={`rounded-full border px-2 font-mono text-xs ${r.injected ? "border-inconclusive/60 text-inconclusive" : "border-kill/60 text-kill"}`}
                  >
                    {r.injected ? "↺ injected" : "↺ real"}
                  </span>
                ))}
                <span className={`font-mono text-xs uppercase tracking-[0.08em] ${STATUS_COLOR[status]}`}>
                  {agent === "naysayer" && followups > 0 && <span className="sr-only">{followups} follow-ups requested, </span>}
                  {STATUS_TEXT[status]}
                </span>
              </span>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

// Activity feed (spec 16, item 3): terse lines for agent starts and finishes, LLM calls, tool calls, data
// progress, follow-up requests and recoveries (REAL or INJECTED). Fills the stretch where the panels are
// still waiting. Each line fades in once (180 ms); the list keeps the newest line in view.
import { motion } from "framer-motion";
import { useEffect, useRef } from "react";
import type { FeedLine, UiState } from "../state";
import { AGENT_LABEL } from "./AgentGraph";

const TONE: Record<FeedLine["tone"], string> = { info: "text-text/80", ok: "text-text", bad: "text-kill", injected: "text-inconclusive" };

function offset(ts: string, start: string | null): string {
  const ms = start ? Date.parse(ts) - Date.parse(start) : NaN;
  if (!Number.isFinite(ms)) return "--:--";
  const s = Math.max(0, Math.floor(ms / 1000));
  return `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;
}

export function Feed({ state, reduced }: { state: UiState; reduced: boolean }) {
  const ref = useRef<HTMLOListElement>(null);
  useEffect(() => {
    const el = ref.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [state.feed.length]);

  if (state.feed.length === 0) {
    return (
      <p className="text-sm text-muted">
        {state.phase === "idle" ? "Each agent step, tool call and LLM call is listed here as the audit replays." : "Waiting for the first agent step…"}
      </p>
    );
  }
  return (
    <ol ref={ref} role="log" aria-label="Agent activity" className="-mr-2 h-full overflow-y-auto pr-2 font-mono text-xs leading-relaxed">
      {state.feed.map((l) => (
        <motion.li
          key={l.seq}
          initial={reduced ? false : { opacity: 0, y: 4 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.18, ease: [0.16, 1, 0.3, 1] }}
          className="grid grid-cols-[3rem_minmax(0,1fr)] gap-2 py-0.5"
        >
          <span className="tabular-nums text-muted">{offset(l.ts, state.startedAt)}</span>
          <span className={`break-words ${TONE[l.tone]}`}>
            {l.agent && <span className="mr-2 font-semibold text-text">{AGENT_LABEL[l.agent]}</span>}
            {l.text}
          </span>
        </motion.li>
      ))}
    </ol>
  );
}

import { useEffect, useState, type FormEvent, type ReactNode } from "react";
import type { UiState } from "../state";
import { displayIdea, runLabel } from "../useAudit";

export interface Chip {
  label: string;
  available: boolean;
}

function runDate(ts: string | null): string {
  if (!ts) return "";
  const d = new Date(ts);
  return Number.isNaN(d.getTime()) ? ts : d.toISOString().slice(0, 16).replace("T", " ") + " UTC";
}

export function CommandBar({ state, mode, chips, onSubmit, controls, error, onDismissError }: {
  state: UiState; mode: "replay" | "live"; chips: Chip[]; onSubmit: (text: string) => void; controls: ReactNode;
  error: string | null; onDismissError: () => void;
}) {
  const [text, setText] = useState("");
  // The input always names the recording on screen, whether it was typed or picked from a chip.
  useEffect(() => {
    if (state.idea) setText(displayIdea(state.idea));
  }, [state.idea]);
  const submit = (e: FormEvent) => {
    e.preventDefault();
    onSubmit(text);
  };
  const isReplay = mode === "replay";
  const label = runLabel(state.idea, state.provider);
  return (
    <section className="rounded-md border border-line bg-panel px-4 py-3">
      <div className="flex items-center gap-4">
        <div className="flex shrink-0 items-baseline gap-3">
          <h1 className="text-base font-semibold tracking-tight">Strategy Auditor</h1>
          <span className="hidden font-mono text-xs uppercase tracking-[0.08em] text-muted 2xl:inline">mission control</span>
        </div>
        <form onSubmit={submit} className="flex min-w-0 flex-1 items-center gap-2">
          <input
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder="Type a recorded trading idea, or pick one below…"
            aria-label="Trading idea"
            required
            minLength={3}
            className="h-9 min-w-0 flex-1 rounded border border-muted/60 bg-bg px-3 text-sm text-text placeholder:text-muted focus:border-accent"
          />
          <button type="submit" className="h-9 shrink-0 rounded bg-accent px-4 text-sm font-semibold text-bg transition-[filter] duration-150 hover:brightness-110">
            Audit
          </button>
        </form>
        <span
          className={`flex h-7 shrink-0 items-center gap-2 rounded-full border px-3 font-mono text-xs font-semibold tracking-[0.08em] ${isReplay ? "border-line text-muted" : "border-promising/60 text-promising"}`}
          title={isReplay ? "Replaying a recorded events.jsonl" : "Live audit"}
        >
          <span className={`h-1.5 w-1.5 rounded-full ${isReplay ? "bg-muted" : "bg-promising"}`} />
          {isReplay ? "REPLAY" : "LIVE"}
          {isReplay && state.startedAt && <span className="font-normal">· {runDate(state.startedAt)}</span>}
        </span>
        {controls}
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        {chips.map((c) => (
          <button
            key={c.label}
            type="button"
            onClick={() => onSubmit(c.label)}
            disabled={!c.available}
            title={c.available ? `Replay the recorded audit of "${c.label}"` : "Not recorded yet: run scripts/demo_audits.py to record it"}
            className="rounded-full border border-line bg-bg px-3 py-1 text-xs text-muted transition-colors duration-150 enabled:hover:border-accent enabled:hover:text-text disabled:cursor-not-allowed disabled:opacity-50"
          >
            {c.label}
            {!c.available && <span className="ml-1">· not recorded</span>}
          </button>
        ))}
        {error ? (
          <div role="alert" className="flex min-w-0 flex-1 items-center gap-3 pl-2 text-sm text-kill">
            <span className="min-w-0">{error}</span>
            <button type="button" onClick={onDismissError} className="shrink-0 rounded border border-line px-2 py-0.5 text-xs text-text transition-colors duration-150 hover:border-accent">
              Dismiss
            </button>
          </div>
        ) : (
          <div className="min-w-0 flex-1 truncate pl-2 text-sm" aria-live="polite">
            {state.whatTested ? (
              <>
                <span className="font-mono text-xs uppercase tracking-[0.08em] text-muted">tested </span>
                <span className="text-text">{state.whatTested}</span>
                {state.planHash && <span className="ml-2 font-mono text-xs text-muted">v0 {state.planHash.slice(0, 12)}</span>}
              </>
            ) : null}
          </div>
        )}
        {label && (
          <span className="flex h-7 shrink-0 items-center rounded-full border border-kill/70 px-3 font-mono text-xs font-semibold tracking-[0.08em] text-kill" title={state.idea}>
            {label}
          </span>
        )}
      </div>
    </section>
  );
}

